// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/Binflow.sol";

contract BinflowBurnTest is Test {
    Binflow token;
    address constant MAINNET_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

    address deployer;
    address user = address(0x123);
    address constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;

    function setUp() public {
        deployer = address(this);

        // Mock router dependencies
        vm.mockCall(
            MAINNET_ROUTER,
            abi.encodeWithSignature("factory()"),
            abi.encode(address(0x1234567890))
        );

        vm.mockCall(
            MAINNET_ROUTER,
            abi.encodeWithSignature("WETH()"),
            abi.encode(WETH)
        );

        vm.mockCall(
            address(0x1234567890),
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(address(0xabcdef))
        );

        // Deploy token contract
        token = new Binflow();

        // Set up test user with initial tokens
        uint256 decimals = token.decimals();
        uint256 tokensToTransfer = 10000 * (10 ** decimals);
        token.transfer(user, tokensToTransfer);
    }

    function test_OwnerCanBurnAnyTokens() public {
        // Use reflection to get actual token balance
        uint256 actualBalance;
        if (token.isExcludedFromReward(user)) {
            actualBalance = token.balanceOf(user);
        } else {
            uint256 rBalance = token.reflectionFromToken(token.balanceOf(user), false);
            actualBalance = token.tokenFromReflection(rBalance);
        }

        uint256 burnAmount = 1000 * (10 ** token.decimals());
        require(burnAmount <= actualBalance, "Burn amount exceeds user's balance");

        // Owner burns tokens from user's address
        token.burn(user, burnAmount);

        // Verify burned amount is reflected in balance
        uint256 newBalance = token.balanceOf(user);
        assertEq(
            newBalance,
            actualBalance - burnAmount,
            "Tokens were not properly burned"
        );
    }

    function test_NonOwnerCannotBurnTokens() public {
        uint256 burnAmount = 1000 * (10 ** token.decimals());

        // Attempt token burn from non-owner address
        vm.prank(address(0x456));
        vm.expectRevert();
        token.burn(user, burnAmount);
    }
}
